const CACHE='mec-lernpass-v1.6.1';
const FILES=['./','index.html','styles.css','updates.css','workbook.css','data.js','flow.js','core.js','workbook.js','explanations.js','writer.js','insights.js','sync.js','planner-ui.js','unit-ui.js','app.js','icon.svg','manifest.webmanifest','fonts/Inter.ttf'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const file of FILES){try{const response=await fetch(file,{credentials:'same-origin',cache:'reload'});if(response.ok&&!response.redirected)await cache.put(file,response);}catch{}}await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('mec-lernpass-')&&name!==CACHE)await caches.delete(name);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;const path=new URL(event.request.url).pathname;if(path.startsWith('/api/'))return;if(!FILES.some(file=>path.endsWith('/'+file.replace('./',''))) && event.request.mode!=='navigate')return;event.respondWith((async()=>{try{const response=await fetch(event.request);if(response.ok&&!response.redirected){const cache=await caches.open(CACHE);await cache.put(event.request,response.clone());}return response;}catch{const cached=await caches.match(event.request);if(cached)return cached;if(event.request.mode==='navigate')return (await caches.match('index.html'))||Response.error();return Response.error();}})());});
